// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ChangePassword Replace a temporary password and activate the account
	// (POST /api/v1/auth/change-password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// Login Start a server-side session with local credentials
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current server-side session
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ListRegions Return the versioned selectable Russian region catalog
	// (GET /api/v1/catalog/regions)
	ListRegions(ctx context.Context, request ListRegionsRequestObject) (ListRegionsResponseObject, error)
	// ListResidentialComplexes Return the cached residential complexes for one selected region
	// (GET /api/v1/catalog/regions/{regionCode}/complexes)
	ListResidentialComplexes(ctx context.Context, request ListResidentialComplexesRequestObject) (ListResidentialComplexesResponseObject, error)
	// ListSegments Return stable real-estate segments and current ЕИСЖС support
	// (GET /api/v1/catalog/segments)
	ListSegments(ctx context.Context, request ListSegmentsRequestObject) (ListSegmentsResponseObject, error)
	// ListEmployees List local employee accounts
	// (GET /api/v1/employees)
	ListEmployees(ctx context.Context, request ListEmployeesRequestObject) (ListEmployeesResponseObject, error)
	// CreateEmployee Create a local employee account and issue a temporary password
	// (POST /api/v1/employees)
	CreateEmployee(ctx context.Context, request CreateEmployeeRequestObject) (CreateEmployeeResponseObject, error)
	// UpdateEmployee Change an employee display name or role
	// (PATCH /api/v1/employees/{employeeId})
	UpdateEmployee(ctx context.Context, request UpdateEmployeeRequestObject) (UpdateEmployeeResponseObject, error)
	// DeactivateEmployee Deactivate an employee and revoke all server-side sessions
	// (POST /api/v1/employees/{employeeId}/deactivate)
	DeactivateEmployee(ctx context.Context, request DeactivateEmployeeRequestObject) (DeactivateEmployeeResponseObject, error)
	// ResetEmployeePassword Issue a replacement temporary password and revoke all sessions
	// (POST /api/v1/employees/{employeeId}/reset-password)
	ResetEmployeePassword(ctx context.Context, request ResetEmployeePasswordRequestObject) (ResetEmployeePasswordResponseObject, error)
	// RestoreEmployee Restore an employee by issuing a new temporary password
	// (POST /api/v1/employees/{employeeId}/restore)
	RestoreEmployee(ctx context.Context, request RestoreEmployeeRequestObject) (RestoreEmployeeResponseObject, error)
	// RevokeEmployeeSessions Revoke every server-side session for an employee
	// (POST /api/v1/employees/{employeeId}/revoke-sessions)
	RevokeEmployeeSessions(ctx context.Context, request RevokeEmployeeSessionsRequestObject) (RevokeEmployeeSessionsResponseObject, error)
	// GetCurrentUser Return the current authenticated employee
	// (GET /api/v1/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// ListAnalyticalSessions List shared non-deleted analytical sessions
	// (GET /api/v1/sessions)
	ListAnalyticalSessions(ctx context.Context, request ListAnalyticalSessionsRequestObject) (ListAnalyticalSessionsResponseObject, error)
	// CreateAnalyticalSession Create one immutable current-only analytical session
	// (POST /api/v1/sessions)
	CreateAnalyticalSession(ctx context.Context, request CreateAnalyticalSessionRequestObject) (CreateAnalyticalSessionResponseObject, error)
	// GetAnalyticalSession Return one shared non-deleted analytical session
	// (GET /api/v1/sessions/{sessionId})
	GetAnalyticalSession(ctx context.Context, request GetAnalyticalSessionRequestObject) (GetAnalyticalSessionResponseObject, error)
	// CollectCurrentSnapshot Advance one current-only ЕИСЖС collection request
	// (POST /api/v1/sessions/{sessionId}/collect)
	CollectCurrentSnapshot(ctx context.Context, request CollectCurrentSnapshotRequestObject) (CollectCurrentSnapshotResponseObject, error)
	// GetLiveness Report whether the API process is alive
	// (GET /health/live)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// GetReadiness Report whether required dependencies are available
	// (GET /health/ready)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ChangePassword operation middleware
func (sh *strictHandler) ChangePassword(w http.ResponseWriter, r *http.Request, params ChangePasswordParams) {
	var request ChangePasswordRequestObject

	request.Params = params

	var body ChangePasswordJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ChangePassword(ctx, request.(ChangePasswordRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ChangePassword")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ChangePasswordResponseObject); ok {
		if err := validResponse.VisitChangePasswordResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

